@pytest.mark.parametrize("row", [])
def test_search_get_table_driven(
    row: Dict[str, Any],
    api_client,
    api_spec_validator: SwaggerSchemaValidator,
    endpoint_path: str,
    valid_api_key: Optional[str],
    params_factory: Callable[[Dict[str, Any], Optional[str]], Dict[str, Any]],
    request_schema: Dict[str, Any],
    success_response_schema: Dict[str, Any],
    error_response_schema: Dict[str, Any],
):
    """
    Table-driven test for GET /v1/search.json using data from search_json.json.

    Behavior:
    - Builds request params solely from JSON file and fixtures (no hardcoded payloads).
    - Validates request against the request schema using SwaggerSchemaValidator before sending.
    - Sends request via shared ApiClient fixture.
    - Asserts status code equals the one specified in the JSON row.
    - Validates response body with appropriate schema (200 => success schema, 4xx => error schema).
    - Skips 'Success' scenarios when a valid API key is not available.
    """
    scenario = (row.get("scenario") or "").strip().lower()
    expected_status = row.get("statusCode")

    # Enforce availability of valid API key for success scenarios
    if scenario in ("success", "happy_path", "ok") and not valid_api_key:
        pytest.skip("No valid_api_key configured; skipping success scenario as auth is handled elsewhere.")

    # Build params strictly from provided JSON row + fixtures
    params = params_factory(row, valid_api_key)

    # Validate request (for negative scenarios like 'missing_q', validation may fail; we proceed).
    try:
        api_spec_validator.validate_with_schema(params, request_schema)
    except Exception as _e:
        # For scenarios that intentionally violate the schema (e.g., missing 'q'),
        # we continue to exercise server-side validation paths.
        pass

    # Only GET is defined by the spec for this endpoint
    response = api_client.get(endpoint_path, params=params)

    # Validate expected status code from JSON file
    assert isinstance(expected_status, int), "statusCode must be an integer in test data"
    assert response.status_code == expected_status, f"Unexpected status code for scenario {row}"

    # Validate response content-type is JSON-like if header is present
    ctype = response.headers.get("Content-Type", "")
    assert "json" in ctype.lower() or "javascript" in ctype.lower() or ctype == "", "Response content-type must be JSON"

    # Parse JSON (empty body for some 4xx cases might be possible; we handle gracefully)
    try:
        body = response.json()
    except ValueError:
        # If body is not JSON but status is 204 or similar, it would be acceptable;
        # However, per spec we expect JSON for 200/4xx responses.
        body = None

    # Validate response body schema using validator
    if expected_status == 200:
        # For 200, body must be an array per spec
        assert isinstance(body, list), "200 response must be an array"
        api_spec_validator.validate_with_schema(body, success_response_schema)
    elif expected_status in (400, 401, 403):
        assert isinstance(body, dict), f"{expected_status} response must be an object"
        api_spec_validator.validate_with_schema(body, error_response_schema)
    else:
        # If new codes are added in test data, we don't assert schema here
        pytest.skip(f"No schema validation configured for status {expected_status}")


